\begin{lemma}
\label{lemma-points-above-point}
Let $\mathcal{C}$, $p$, $u$, $U$ be as in
Lemma \ref{lemma-point-localize}.
The construction of
Lemma \ref{lemma-point-localize}
gives a one to one correspondence between points $q$
of $\mathcal{C}/U$ lying over $p$ and elements $x$ of $u(U)$.
\end{lemma}

