\begin{definition}
\label{definition-2-morphism-topoi}
Let $f, g : \Sh(\mathcal{C}) \to \Sh(\mathcal{D})$
be two morphisms of topoi. A {\it 2-morphism from $f$ to $g$}
is given by a transformation of functors $t : f_* \to g_*$.
\end{definition}

